before(async()=>{({fixture}=await import(pathToFileURL(resolve(process.env.TRAINING_WORKER_ROOT,'test/helpers/practice-fixture.mjs')).href));browser=await chromium.launch({headless:true,executablePath:process.env.HQ_TEST_BROWSER});server=http.createServer(async(req,res)=>{const u=new URL(req.url,'http://local');if(u.pathname==='/fixture'){res.setHeader('Content-Type','text/html; charset=utf-8');return res.end(`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/practice-tools.css"><main id="root"></main><script src="/practice-intake.js"></script><script src="/practice-reference.js"></script><script src="/practice-reference-ui.js"></script><script src="/practice-calculators.js"></script><script src="/practice-acid-base.js"></script><script src="/practice-calculator-workspace.js"></script><script src="/practice-calculator-simple.js"></script><script src="/practice-tools.js"></script><script>var identity='a';var selected={id:'p',name:'시험 환자',guardianName:'시험 보호자'};var app=PracticeTools.mount(document.getElementById('root'),{ready:()=>true,identity:()=>identity,can:()=>true,navigate:()=>app.open(),patient:()=>selected,request:async(path,o={})=>{var r=await fetch('/api'+path+(path.includes('?')?'&':'?')+'test='+new URLSearchParams(location.search).get('test'),o);var d=await r.json();if(!r.ok)throw Error(d.error);return d;}});app.open();</script></html>`);}if(u.pathname.startsWith('/api/')){const f=fixtures.get(u.searchParams.get('test'));let raw='';for await(const c of req)raw+=c;const b=raw?JSON.parse(raw):{};try{const ops=u.pathname.startsWith('/api/operations'),extra=u.pathname.startsWith('/api/practice'),path=u.pathname.replace(ops?'/api/operations':extra?'/api/practice':'/api/intakes','')+u.search;const d=await (ops?f.ops:extra?f.extras:f.intake)(path,req.method,b);res.setHeader('Content-Type','application/json');res.end(JSON.stringify(d));}catch(e){res.writeHead(e.statusCode||500,{'Content-Type':'application/json'});res.end(JSON.stringify({error:e.message}));}return;}if(!/^\/[a-zA-Z0-9.-]+$/.test(u.pathname)){res.writeHead(404);return res.end();}try{res.setHeader('Content-Type',({'.js':'text/javascript','.css':'text/css','.html':'text/html','.woff2':'font/woff2'})[extname(u.pathname)]||'text/plain');res.end(readFileSync(resolve(root,u.pathname.slice(1))));}catch{res.writeHead(404);res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));origin='http://127.0.0.1:'+server.address().port;});
after(async()=>{await browser?.close();if(server)await new Promise(r=>server.close(r));});
const bicarbProtocol={kind:'protocol',title:'시험 병원 중탄산 서식',calculator:'bicarbonate',species:'dog',indication:'검증용 교정 계획',source:'시험 병원 승인 기준',defaults:{method:'hco3',target:'18',factor:'0.3',fraction:'50',stock:'1',volume:'30',minutes:'60',diluent:'시험 희석액'},confirm:true};
async function openProtocol(p,kind='bicarbonate'){
 await p.getByRole('button',{name:'임상 계산기',exact:true}).click();await p.locator('[data-ref-species]').selectOption('dog');await p.locator('[data-common-weight]').fill('5');
 const target=({dose:'med',ag:'acid',bicarbonate:'acid'}[kind]||kind);if(p.viewportSize().width<=800)await p.locator('[data-calc-jump]').selectOption(target);else await p.locator('[data-kind='+target+']').click();if(kind==='bicarbonate')await p.locator('[data-acid-view=bicarbonate]').click();return p.locator('[data-calc='+kind+']');
}
async function chooseProtocol(form,id){await form.locator('[data-protocol]').selectOption(id);await form.locator('[data-protocol-status]').filter({hasText:'병원 서식을 불러왔습니다.'}).waitFor();}
