async function openSetup(p){await p.locator('[data-settings],[data-reference-picker],[data-calc-records],[data-legacy-presets],.pt-patient-options,.pt-view-options').evaluateAll(nodes=>nodes.forEach(n=>n.open=true));}
async function page(t,f,width=1280){const id=crypto.randomUUID();fixtures.set(id,f);const p=await browser.newPage({viewport:{width,height:900}});t.after(()=>p.close());await p.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());await p.goto(origin+'/fixture?test='+id);await p.getByRole('button',{name:'업무 시작·배정',exact:true}).waitFor();return p;}
for(const width of [390,1280])test('SOP 서식→배정→보류→인계 실제 화면 '+width,async t=>{const f=fixture(t);await f.sop();const p=await page(t,f,width);await p.getByRole('button',{name:'서식 관리',exact:true}).click();await p.getByRole('dialog').getByRole('button',{name:'SOP에서 서식 만들기',exact:true}).click();await p.locator('select[name=source]').selectOption({index:1});await p.locator('textarea[name=items]').fill('기구를 확인합니다\n대기실 환경을 확인합니다');await p.getByRole('button',{name:'서식 저장',exact:true}).click();await p.getByRole('dialog').waitFor({state:'hidden'});await p.getByRole('button',{name:'업무 시작·배정',exact:true}).click();await p.locator('select[name=template]').selectOption({index:1});await p.getByRole('button',{name:'업무 배정',exact:true}).click();await p.getByRole('dialog').waitFor({state:'hidden'});await p.getByRole('button',{name:'업무 확인·인계',exact:true}).click();await p.getByRole('button',{name:'상태·메모 변경',exact:true}).first().click();await p.locator('select[name=state]').selectOption('held');await p.locator('textarea[name=note]').fill('멸균 확인을 기다리고 있습니다');await p.getByRole('button',{name:'확인 기록 저장',exact:true}).click();await p.getByText('멸균 확인을 기다리고 있습니다',{exact:true}).waitFor();assert.ok(await p.getByRole('dialog').evaluate(e=>e.scrollWidth<=e.clientWidth+1));await p.screenshot({path:resolve(root,'../practice-checklist-'+width+'.png'),fullPage:true});await p.getByRole('button',{name:'다른 직원에게 인계',exact:true}).click();await p.locator('select[name=assignee]').selectOption('staff');await p.locator('textarea[name=note]').fill('오후 근무자가 확인해주세요');await p.getByRole('button',{name:'인계 기록·담당자 변경',exact:true}).click();await p.getByRole('dialog').waitFor({state:'hidden'});assert.equal(f.sqlite.prepare('SELECT assignee_id FROM care_ops_runs').get().assignee_id,'staff');});
test('문진 확인·환자 연결·검토와 환자 작업공간 필터',async t=>{const f=fixture(t),i=await f.intake('/invites','POST',{});await f.pub(i.token,'POST',f.input());const p=await page(t,f);await p.getByRole('button',{name:'사전문진',exact:true}).click();await p.getByRole('button',{name:'문진 확인',exact:true}).click();await p.getByRole('checkbox').check();await p.getByRole('button',{name:'선택한 환자에 연결',exact:true}).click();await p.getByRole('dialog').waitFor({state:'hidden'});await p.getByRole('button',{name:'문진 확인',exact:true}).click();await p.getByRole('button',{name:'병원 확인 완료',exact:true}).click();await p.getByRole('dialog').waitFor({state:'hidden'});assert.equal(f.sqlite.prepare('SELECT status FROM care_intakes').get().status,'reviewed');await p.evaluate(()=>app.intakeFor({id:'p',name:'시험 환자',guardianName:'시험 보호자'}));await p.getByRole('button',{name:'전체 문진',exact:true}).waitFor();});
test('계산 입력 변경 시 이전 결과 제거·공식과 모바일 표시',async t=>{const f=fixture(t),p=await page(t,f,390);await p.getByRole('button',{name:'임상 계산기',exact:true}).click();await openSetup(p);const form=p.locator('form[data-calc=dose]');await p.locator('[data-common-weight]').fill('5');await form.locator('[name=dose]').fill('2');await form.locator('[name=concentration]').fill('10');await form.getByRole('button',{name:'계산',exact:true}).click();assert.match(await form.locator('output').innerText(),/1 mL\/회/);await p.locator('[data-common-weight]').fill('6');assert.equal(await form.locator('output').innerText(),'');await form.getByRole('button',{name:'계산',exact:true}).click();assert.match(await form.locator('output').innerText(),/1.2 mL\/회/);assert.ok(await p.locator('body').evaluate(e=>e.scrollWidth<=innerWidth));await p.screenshot({path:resolve(root,'../practice-calculators-390.png'),fullPage:true});});
test('공개 문진 입력·동의·중복 방지·개인정보 링크 미노출',async t=>{const f=fixture(t),i=await f.intake('/invites','POST',{}),p=await browser.newPage({viewport:{width:390,height:900}});t.after(()=>p.close());await p.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());if(u.origin===origin)return route.continue();if(u.origin==='https://carestep-ai-api.kk04sdw.workers.dev'&&u.pathname==='/intake/form'){try{const r=await f.pub(req.headers().authorization?.slice(7),req.method(),req.postDataJSON());return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(r)});}catch(e){return route.fulfill({status:e.statusCode||500,contentType:'application/json',body:JSON.stringify({error:e.message})});}}return route.abort();});await p.goto(origin+'/intake.html#'+i.token);await p.locator('[name=guardianName]').fill('시험 보호자');await p.locator('[name=phone]').fill('01012345678');await p.locator('[name=patientName]').fill('시험 환자');await p.locator('[name=species]').selectOption({label:'강아지'});await p.locator('[name=purpose]').fill('식욕 변화를 상담하고 싶습니다');await p.getByRole('checkbox').check();assert.ok(await p.locator('body').evaluate(e=>e.scrollWidth<=innerWidth));await p.screenshot({path:resolve(root,'../practice-intake-390.png'),fullPage:true});await p.getByRole('button',{name:'병원에 문진 제출',exact:true}).click();await p.getByText('병원에 문진을 전달했습니다',{exact:true}).waitFor();assert.equal(f.sqlite.prepare('SELECT COUNT(*) n FROM care_intakes').get().n,1);await p.reload();await p.getByText('제출이 완료된 문진 링크입니다',{exact:true}).waitFor();});
test('병원 변경 후 이전 화면·문진·계산값 제거',async t=>{const f=fixture(t),p=await page(t,f);await p.getByRole('button',{name:'임상 계산기',exact:true}).click();await openSetup(p);await p.locator('[data-common-weight]').fill('5');await p.evaluate(()=>{identity='b';app.clear();});assert.equal(await p.locator('#root').innerText(),'');});
test('현재 CLINIC 문서에서 실무 도구 진입과 사용자 지정 권한',async t=>{const p=await browser.newPage();t.after(()=>p.close());await p.route('**/*',r=>r.request().url().startsWith(origin)?r.continue():r.abort());await p.goto(origin+'/index.html');await p.evaluate(()=>{saasMode='auth';saasSessionMeta={id:'test-session'};saasMe={role:'staff',clinic:{id:'synthetic'},user:{id:'staff'},permissions:{mode:'custom',keys:['operations.read']}};saasRequest=async()=>({ok:true,manager:false,date:'2026-10-22',runs:[],templates:[],members:[],userId:'staff'});showApp();go('practice');});await p.getByRole('button',{name:'업무 체크리스트',exact:true}).waitFor();assert.equal(await p.locator('#viewTitle').innerText(),'실무 도구');assert.equal(await p.getByRole('button',{name:'서식 관리',exact:true}).count(),0);assert.equal(await p.getByRole('button',{name:'임상 계산기',exact:true}).count(),0);await p.evaluate(()=>{saasMe.permissions={mode:'custom',keys:['materials.read','patients.read']};go('practice');});await p.getByRole('button',{name:'임상 계산기',exact:true}).waitFor();assert.equal(await p.locator('form[data-calc=dose]').count(),1);});
test('HOME 연결 환자 문진은 선택 환자로 제출되고 계정 변경 시 닫힘',async t=>{const f=fixture(t),p=await browser.newPage({viewport:{width:390,height:900}});t.after(()=>p.close());await p.route('**/*',async r=>{const u=new URL(r.request().url());if(u.origin===origin)return r.continue();if(u.pathname==='/home/intakes/p'){try{const d=await f.home('p',r.request().method(),r.request().postDataJSON());return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(d)});}catch(e){return r.fulfill({status:e.statusCode||500,contentType:'application/json',body:JSON.stringify({error:e.message})});}}return r.abort();});await p.goto(origin+'/fixture?test=unused');await p.evaluate(()=>{document.body.innerHTML='<main id="dashboardView"><div id="homeHospitalMaterials"></div><button id="homeIntakeOpen">방문 전 문진</button></main>';window.homeMock={token:'test-home',view:'patientView',activePatientId:'p',home:{connections:[{patients:[{id:'p',name:'시험 환자'}]}]}};window.carestepHomeSnapshot=()=>homeMock;});await p.addScriptTag({url:origin+'/practice-intake.js'});await p.getByRole('button',{name:'방문 전 문진',exact:true}).click();await p.locator('[name=patientName]').waitFor();assert.equal(await p.locator('[name=patientName]').inputValue(),'시험 환자');await p.locator('[name=guardianName]').fill('시험 보호자');await p.locator('[name=phone]').fill('01012345678');await p.locator('[name=species]').selectOption({label:'강아지'});await p.locator('[name=purpose]').fill('정기 상담');await p.getByRole('checkbox').check();await p.getByRole('button',{name:'병원에 문진 제출',exact:true}).click();await p.getByText('병원에 문진을 전달했습니다',{exact:true}).waitFor();assert.equal(f.sqlite.prepare('SELECT patient_id FROM care_intakes').get().patient_id,'p');await p.evaluate(()=>{homeMock.token='';document.getElementById('dashboardView').append(document.createElement('span'));});await p.getByRole('dialog').waitFor({state:'detached'});});
test('반복 설정 저장→실제 자동 생성→빠른 완료→중지',async t=>{const f=fixture(t),source=await f.sop();await f.ops('/templates','POST',{sourceVersionId:source,title:'오픈 점검',items:['준비 확인']});const p=await page(t,f,390);await openWorkSettings(p);await p.getByRole('button',{name:'반복 업무 관리',exact:true}).click();await p.getByRole('button',{name:'반복 업무 추가',exact:true}).click();await p.locator('[name=assignee]').selectOption('staff');await p.locator('[name=frequency]').selectOption('weekly');const weekday=new Date(f.c.practiceToday()+'T00:00:00Z').getUTCDay();await p.locator('[name=weekday][value="'+weekday+'"]').check();await p.locator('[name=dueTime]').fill('18:00');await p.getByRole('button',{name:'반복 설정 저장',exact:true}).click();await p.getByRole('heading',{name:'반복 업무 관리',exact:true}).waitFor();await f.c.runPracticeScheduleCycle(f.env);await p.getByRole('button',{name:'닫기',exact:true}).click();await p.getByRole('button',{name:'새로고침',exact:true}).click();await p.getByRole('button',{name:'업무 확인·인계',exact:true}).click();await p.getByRole('button',{name:'완료',exact:true}).click();await p.getByRole('button',{name:'미확인으로 변경',exact:true}).waitFor();assert.equal(f.sqlite.prepare('SELECT status FROM care_ops_runs').get().status,'done');await p.screenshot({path:resolve(root,'../practice-v2-quickcheck.png'),fullPage:true});await p.getByRole('button',{name:'닫기',exact:true}).click();await openWorkSettings(p);await p.getByRole('button',{name:'반복 업무 관리',exact:true}).click();await p.getByRole('button',{name:'반복 중지',exact:true}).click();await p.getByText(/중지/).waitFor();assert.equal(f.sqlite.prepare('SELECT active FROM care_ops_schedules').get().active,0);});
test('환자 검색을 문진 안에서 연결하고 상태로 필터',async t=>{const f=fixture(t),i=await f.intake('/invites','POST',{});await f.pub(i.token,'POST',f.input());const p=await page(t,f);await p.route('**/api/patient-directory?**',r=>r.fulfill({contentType:'application/json',body:JSON.stringify({ok:true,patients:[{id:'p',name:'시험 환자',guardianName:'시험 보호자',guardianPhoneLast4:'5678'}],pagination:{total:1}})}));await p.evaluate(()=>selected=null);await p.getByRole('button',{name:'사전문진',exact:true}).click();await p.locator('[data-intake-filter=unmatched]').click();await p.getByRole('button',{name:'문진 확인',exact:true}).click();await p.locator('[name=q]').fill('시험');await p.getByRole('button',{name:'환자 검색',exact:true}).click();await p.locator('[data-pick=p]').click();await p.locator('[data-match-confirm]').check();await p.getByRole('button',{name:'이 환자에 연결',exact:true}).click();await p.getByRole('dialog').waitFor({state:'hidden'});assert.equal(await p.getByRole('button',{name:'문진 확인',exact:true}).count(),0);await p.locator('[data-intake-filter=new]').click();await p.getByRole('button',{name:'문진 확인',exact:true}).waitFor();});
test('계산기 환자 체중·정제 총량·수액·확인과 환자변경 초기화',async t=>{const f=fixture(t);f.sqlite.exec("INSERT INTO care_patient_events VALUES('w','a','p','weight','clinic','active',5,'2026-10-22','2026-10-22')");const p=await page(t,f,390);await p.getByRole('button',{name:'임상 계산기',exact:true}).click();await openSetup(p);await p.getByRole('button',{name:'측정일을 확인하고 체중 사용',exact:true}).click();const form=p.locator('[data-calc=dose]');assert.equal(await form.locator('[name=weight]').inputValue(),'5');await form.locator('[name=dose]').fill('2');await form.locator('[name=form]').selectOption('tablet');await form.locator('[name=concentration]').fill('20');await form.locator('[name=times]').fill('2');await form.locator('[name=days]').fill('3');await form.getByRole('button',{name:'계산',exact:true}).click();assert.match(await form.locator('output').innerText(),/전체 필요량 3 정/);assert.equal(await form.getByRole('button',{name:'결과 복사',exact:true}).isEnabled(),false);await form.locator('[data-checked]').check();assert.equal(await form.getByRole('button',{name:'결과 복사',exact:true}).isEnabled(),true);await chooseKind(p,'fluid');const fluid=p.locator('[data-calc=fluid]');await fluid.locator('[name=rate]').fill('3');await fluid.locator('[name=hours]').fill('4');await fluid.locator('[name=volume]').fill('60');await fluid.locator('[name=factor]').fill('20');await fluid.getByRole('button',{name:'계산',exact:true}).click();assert.match(await fluid.locator('output').innerText(),/주입 속도 15 mL\/hr/);assert.match(await fluid.locator('output').innerText(),/5 gtt\/min/);assert.ok(await p.locator('body').evaluate(e=>e.scrollWidth<=innerWidth));await p.screenshot({path:resolve(root,'../practice-v2-fluid-390.png'),fullPage:true});await p.setViewportSize({width:1280,height:900});await p.screenshot({path:resolve(root,'../practice-v2-fluid-1280.png'),fullPage:true});await p.setViewportSize({width:390,height:900});await fluid.locator('[name=rate]').fill('4');assert.equal(await fluid.locator('output').innerText(),'');await p.evaluate(()=>selected={id:'other',name:'변경 환자'});await fluid.getByRole('button',{name:'계산',exact:true}).click();await p.getByText('변경 환자 · 보호자',{exact:false}).waitFor();assert.equal(await p.locator('[data-calc=dose] [name=weight]').inputValue(),'');});
