test('업무 상태 집계·검색·지난 완료 표시·모바일 정렬',async t=>{
 const f=fixture(t),source=await f.sop(),template=await f.ops('/templates','POST',{sourceVersionId:source,title:'진료실 오픈',items:['장비 확인','재고 확인']});const date=new Date(Date.now()+32400000).toISOString().slice(0,10);
 for(const [occurrence,status] of [['오전','open'],['오후','held'],['마감','done']]){const run=await f.ops('/runs','POST',{templateId:template.id,templateRevision:1,assigneeId:'owner',date,occurrence});if(status==='held')await f.ops('/runs/'+run.id,'PATCH',{revision:1,action:'check',index:0,state:'held',note:'확인 대기'});if(status==='done'){await f.ops('/runs/'+run.id,'PATCH',{revision:1,action:'check',index:0,state:'done'});await f.ops('/runs/'+run.id,'PATCH',{revision:2,action:'check',index:1,state:'done'});}}
 const p=await page(t,f,390);assert.equal(await p.locator('[data-ops-list] article').count(),2);await p.locator('[data-ops-filter=all]').click();assert.equal(await p.locator('[data-ops-list] article').count(),3);await p.locator('[data-ops-filter=held]').click();assert.equal(await p.locator('[data-ops-list] article').count(),1);await p.locator('[data-ops-filter=all]').click();await p.locator('[data-ops-search]').fill('오전');assert.equal(await p.locator('[data-ops-list] article').count(),1);await p.locator('[data-ops-search]').fill('없음');await p.getByText('조건에 맞는 업무가 없습니다.',{exact:true}).waitFor();await p.locator('[data-ops-search]').fill('');assert.ok(await p.locator('body').evaluate(e=>e.scrollWidth<=innerWidth));await p.screenshot({path:resolve(root,'../practice-ops-390.png'),fullPage:true});await p.setViewportSize({width:1440,height:1000});await p.screenshot({path:resolve(root,'../practice-ops-1440.png'),fullPage:true});
 f.sqlite.prepare("UPDATE care_ops_runs SET work_date='2020-01-02' WHERE status='done'").run();await p.locator('[data-date]').fill('2020-01-02');await p.locator('[data-ops-list] article').waitFor();assert.equal(await p.getByText('지난 미완료',{exact:true}).count(),0);await p.locator('[data-today]').click();await p.locator('[data-date][value="'+date+'"]').waitFor();
});

test('사전문진 검색과 증상·추가 전달사항의 바로 보이는 상세',async t=>{
 const f=fixture(t);await f.home('p','POST',f.input({symptoms:'식후 구토',other:'사료 변경',requestKey:'intake-search-00001'}));const p=await page(t,f,390);await p.getByRole('button',{name:'사전문진',exact:true}).click();await p.locator('[data-intake-search]').fill('구토');assert.equal(await p.locator('[data-intake-list] article').count(),1);assert.ok(await p.locator('body').evaluate(e=>e.scrollWidth<=innerWidth));await p.screenshot({path:resolve(root,'../practice-intake-390.png'),fullPage:true});await p.getByRole('button',{name:'문진 확인',exact:true}).click();await p.locator('dialog .pt-notice').first().getByText('식후 구토',{exact:false}).waitFor();await p.locator('dialog .pt-notice').first().getByText('사료 변경',{exact:false}).waitFor();assert.ok(await p.getByRole('dialog').evaluate(e=>e.scrollWidth<=e.clientWidth+1));await p.screenshot({path:resolve(root,'../practice-intake-detail-390.png'),fullPage:true});
});

test('실제 CLINIC 문서의 산염기 진입·계산·모바일 배치',async t=>{const p=await browser.newPage({viewport:{width:390,height:900}});t.after(()=>p.close());const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.route('**/*',r=>r.request().url().startsWith(origin)?r.continue():r.abort());await p.goto(origin+'/index.html');await p.evaluate(()=>{saasMode='auth';saasSessionMeta={id:'acid-test'};saasMe={role:'owner',clinic:{id:'synthetic'},user:{id:'owner'}};saasRequest=async path=>path.includes('/presets')?{items:[],canManage:true}:{ok:true,runs:[],templates:[],members:[],manager:true,userId:'owner'};showApp();go('practice');});await p.getByRole('button',{name:'임상 계산기',exact:true}).click();await openSetup(p);await p.locator('[data-ref-species]').selectOption('dog');await chooseKind(p,'acid');const ag=p.locator('[data-calc=ag]');for(const [k,v] of Object.entries({na:'145',k:'4',cl:'110',hco3:'20'}))await ag.locator('[name='+k+']').fill(v);await ag.getByRole('button',{name:'계산',exact:true}).click();assert.match(await ag.locator('output').innerText(),/AG 19 mEq\/L/);assert.ok(await p.locator('#practiceRoot').evaluate(e=>e.scrollWidth<=e.clientWidth+1));assert.deepEqual(errors,[]);await p.screenshot({path:resolve(root,'../acid-base-clinic-390.png'),fullPage:true});});

async function chooseKind(p,kind){if(p.viewportSize().width<=800)await p.locator('[data-calc-jump]').selectOption(kind);else await p.locator('[data-kind='+kind+']').click();await p.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));}
async function openWorkSettings(p){const d=p.locator('.pt-work-settings');if(!await d.evaluate(e=>e.open))await d.locator('summary').click();}
